// ---------------------------------------------------------------------------
// Hero / Home
// ---------------------------------------------------------------------------

@Composable
fun HeroSection() {
    Box(SectionStyle.toModifier().id("home")) {
        Box(ResponsiveRowStyle.toModifier().then(SectionInnerStyle.toModifier())) {
            Column(Modifier.fillMaxWidth()) {
                P(EyebrowStyle.toModifier().margin(0.px).toAttrs()) {
                    Text("Grading made simple")
                }

                P(
                    SectionHeadingStyle.toModifier()
                        .margin(top = 12.px, bottom = 14.px)
                        .toAttrs()
                ) {
                    Text("Grade smarter, spend less time on spreadsheets.")
                }

                P(SectionSubtitleStyle.toModifier().margin(0.px).toAttrs()) {
                    Text(
                        "Student Grading & Records Platform\n" +
                                "for Multiple Institutions operating\n" +
                                "under NACTVET Regulations"
                    )
                }

                Box(ButtonGroupStyle.toModifier().margin(top = 28.px)) {
                    Button(
                        onClick = {},
                        modifier = PrimaryButtonStyle.toModifier()
                    ) {
                        Link(
                            "#downloads",
                            "Download Now",
                            Modifier.color(Colors.White)
                        )
                    }

                    Button(
                        onClick = {},
                        modifier = SecondaryButtonStyle.toModifier()
                    ) {
                        Link(
                            "#docs",
                            "Read the docs",
                            Modifier.color(GradeMateColors.TextPrimary)
                        )
                    }
                }
            }

            Img(
                src = "/welcome.jpeg",
                attrs = Modifier
                    .width(100.percent)
                    .borderRadius(16.px)
                    .styleModifier {
                        property("max-width", "420px")
                        property("height", "auto")
                        property("object-fit", "contain")
                    }
                    .toAttrs()
            )
        }
    }
}