@Composable
fun NavBar() {
    var menuOpen by remember { mutableStateOf(false) }

    Column(
        Modifier
            .fillMaxWidth()
            .position(Position.Sticky)
            .top(0.px)
            .zIndex(50)
            .backgroundColor(GradeMateColors.Surface)
            .styleModifier {
                property(
                    "border-bottom",
                    "1px solid ${GradeMateColors.Border35}"
                )
            }
    ) {
        Row(
            Modifier
                .fillMaxWidth()
                .padding(topBottom = 14.px, leftRight = 20.px),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Img(
                    src = "/grademate.png",
                    attrs = Modifier
                        .size(28.px)
                        .borderRadius(8.px)
                        .toAttrs()
                )

                P(
                    Modifier
                        .margin(left = 10.px)
                        .fontSize(17.px)
                        .fontWeight(FontWeight.Bold)
                        .color(GradeMateColors.Primary)
                        .toAttrs()
                ) {
                    Text("GradeMate")
                }
            }

            // Desktop link row (MD and up)
            Row(DesktopNavLinksStyle.toModifier(), verticalAlignment = Alignment.CenterVertically) {
                Link("#home", "Home", NavLinkStyle.toModifier())
                Link("#docs", "Documentation", NavLinkStyle.toModifier())
                Link("#downloads", "Downloads", NavLinkStyle.toModifier())
                Link("#contact", "Contact", NavLinkStyle.toModifier())
                Button(
                    onClick = {},
                    modifier = PrimaryButtonStyle.toModifier()
                        .width(autoLength)
                        .padding(topBottom = 10.px, leftRight = 18.px)
                        .fontSize(14.px)
                ) {
                    Link("#downloads", "Get GradeMate", Modifier.color(Colors.White))
                }
            }

            // Phone hamburger toggle (hidden at MD and up)
            Column(
                MobileMenuButtonStyle.toModifier().onClick { menuOpen = !menuOpen },
                verticalArrangement = Arrangement.spacedBy(4.px)
            ) {
                repeat(3) {
                    Box(Modifier.width(22.px).height(2.px).backgroundColor(GradeMateColors.TextPrimary))
                }
            }
        }

        // Phone dropdown menu — only ever rendered when open, so it never conflicts
        // with the CSS-driven desktop nav above.
        if (menuOpen) {
            Column(
                Modifier
                    .fillMaxWidth()
                    .padding(leftRight = 20.px, topBottom = 16.px)
                    .styleModifier {
                        property(
                            "border-top",
                            "1px solid ${GradeMateColors.Border}"
                        )
                    }
                ,
                verticalArrangement = Arrangement.spacedBy(18.px)
            ) {
                Link("#home", "Home", NavLinkStyle.toModifier().onClick { menuOpen = false })
                Link("#docs", "Documentation", NavLinkStyle.toModifier().onClick { menuOpen = false })
                Link("#downloads", "Downloads", NavLinkStyle.toModifier().onClick { menuOpen = false })
                Link("#contact", "Contact", NavLinkStyle.toModifier().onClick { menuOpen = false })
            }
        }
    }
}