// ---------------------------------------------------------------------------
// Footer
// ---------------------------------------------------------------------------
//
// Replaces the Footer() function in Index.kt. No new imports needed — Div is
// already required for the Downloads and Contact sections.

@Composable
fun Footer() {
    val year = remember { js("new Date().getFullYear()") as Int }

    Div(attrs = FooterStyle.toModifier().toAttrs()) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.px)) {
            P(
                Modifier
                    .margin(0.px)
                    .fontSize(13.px)
                    .color(GradeMateColors.TextOnDarkSecondary)
                    .toAttrs()
            ) {
                Text("© $year GradeMate")
            }
        }
        Row(Modifier.gap(20.px)) {
            Link("#home", "Home", FooterLinkStyle.toModifier())
            Link("#docs", "Documentation", FooterLinkStyle.toModifier())
            Link("#contact", "Contact", FooterLinkStyle.toModifier())
        }
    }
}